        for i in range(len(string)//2):
            if string[i] != string[-i-1]:
                return False
        return True

    def find_duplicates(self, nums):
        duplicates = []
        seen = set()
        for num in nums:
            if num in seen:
                duplicates.append(num)
            else:
                seen.add(num)
        return duplicates

    def calculate_factorial(self, num):
        factorial = 1
        for i in range(1, num+1):
            factorial *= i
        return factorial

    def find_common_elements(self, nums1, nums2):
        common_elements = []
        for num in nums1:
            if num in nums2:
                common_elements.append(num)
        return common_elements

    def calculate_average(self, nums):
        total = 0
        for num in nums:
            total += num
        return total / len(nums)

    def is_prime(self, num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def remove_duplicates(self, nums):
        new_list = []
        seen = set()
        for num in nums:
            if num not in seen:
                new_list.append(num)
                seen.add(num)
        return new_list

    def find_missing_number(self, nums):
