Here's a Python code that generates prime numbers up to 1000 using the Sieve of Eratosthenes algorithm and multithreading:

```python
import math
from threading import Thread

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def sieve_of_eratosthenes(limit):
    primes = [True] * (limit + 1)
    for num in range(2, int(math.sqrt(limit)) + 1):
        if primes[num]:
            for multiple in range(num*num, limit + 1, num):
                primes[multiple] = False

    return [num for num in range(2, limit + 1) if primes[num]]

def generate_primes(limit):
    with Thread(target=sieve_of_eratosthenes, args=(limit,)) as thread:
        thread.start()
        thread.join()

    primes = sieve_of_eratosthenes(limit)
    return primes

def main():
