```python
import csv
def quicksort_descending(arr):
    if len(arr) <= 1:
        return arr
    else:
        pivot = arr[0]
        left = []
        right = []
        for i in range(1, len(arr)):
            if arr[i] > pivot:
                left.append(arr[i])
            else:
                right.append(arr[i])
        return quicksort_descending(left) + [pivot] + quicksort_descending(right)
def sort_csv_file(input_file, output_file):
    try:
        with open(input_file, 'r') as file:
            csv_reader = csv.reader(file)
            num_elements = int(next(csv_reader)[0])
            arr = [float(i) for i in next(csv_reader)]
            if len(arr) != num_elements:
                raise ValueError("Number of elements in the file does not match the actual number of elements in the array.")
            sorted_arr = quicksort_descending(arr)
            with open(output_file, 'w') as file:
                file.write(','.join([str(i) for i in sorted_arr]))
    except FileNotFoundError:
        print("The input file does not exist.")
    except ValueError as e:
        print(e)
    except Exception as e:
        print("An error occurred:", e)
# Example usage:
sort_csv_file('input.csv', 'output.txt')
```
